import { BrowserProvider, Contract } from 'ethers';

import { votingABI } from "../abi/votingABI";

const CONTRACT_ADDRESS = 0x71901c4789c121C8F228E05e07C0c5C58F2698Ea;

export const getVotingContract = async () => {
  if (window.ethereum) {
    const provider = new ethers.providers.Web3Provider(window.ethereum);
    const signer = provider.getSigner();
    const contract = new ethers.Contract(CONTRACT_ADDRESS, votingABI, signer);
    return contract;
  } else {
    alert("Please install MetaMask");
  }
};
